      "model": "그렇게 쓰면 오해를 살 수 있다. 이번 감소는 계약이 줄거나 보험금을 덜 줘서가 아니라, 국고채 10년물 금리가 2.8%대에서 4.45%로 오르며 **할인율이 올라 현재가치가 작게 계산된 결과**다. 같은 금리 상승으로 우리가 가진 장기채 평가가치도 떨어졌기 때문에 자산 쪽 변화를 함께 보여줘야 한다. 그래서 보고서에는 부채 변동을 금리 효과, 계리가정 변경 효과, 계약 변동 효과로 나눠 적고, **자산과 부채의 듀레이션 차이**가 어떻게 바뀌었는지 덧붙이는 것이 좋다. 금리가 다시 내리면 부채는 그대로 다시 커질 수 있다는 점도 짚어야 한다."
