      "model": "설계사는 **보험금 지급 조건과 심사 방식을 잘 알아서** 서류를 그럴듯하게 맞출 수 있고, 여러 고객을 끌어들일 수 있어 피해가 넓게 퍼져요. 또 회사 안에서 보면 정상 계약처럼 보여 **찾아내기가 어려워요**. 그래서 당국이 징계 이력 사전 확인과 자격 박탈 같은 진입·퇴출 장치를 강화하는 거고, 우리도 대리점 내부통제 점검을 함께 해야 한다고 말씀드리겠어요."
